import {approachFor} from './battle-approaches.js';
import {COMBAT_RELICS,relicState,equippedRelics,equipCombatRelic,unequipCombatRelic} from './combat-relics.js?v=5.16.0';
import {REACTION_RULES} from './combat-reactions.js?v=5.38';
const el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
export function battleRelicMenu(world,onSave,onBack){const root=el('section');root.className='battle-relic-menu';let hero=world.state.party[0];function paint(){root.replaceChildren();const s=world.state,p=relicState(s),h=s.heroes[hero];root.append(el('h3','Rare things, different answers'),el('p','Two relic slots per companion. Each collectible exists once in this journey. Change equipment between battles. Discoveries unlock choices; the campaign remains playable without them.'));
 const crew=el('nav');for(const id of s.recruited){const b=el('button',s.heroes[id].name);b.setAttribute('aria-pressed',String(id===hero));b.onclick=()=>{hero=id;paint();};crew.append(b);}root.append(crew,el('h4',h.name+' · equipped relics'));
 for(let slot=0;slot<2;slot++){const id=h.battleRelics?.[slot],r=COMBAT_RELICS.find(v=>v.id===id),row=el('div');row.className='relic-slot';row.append(el('strong','Slot '+(slot+1)+' · '+(r?r.name:'Empty')));if(r)row.append(el('p',r.effect));const clear=el('button','Remove');clear.disabled=!r||s.mode==='battle';clear.onclick=()=>{unequipCombatRelic(s,hero,slot);onSave();paint();};row.append(clear);root.append(row);}
 for(const r of COMBAT_RELICS){const own=p.owned.includes(r.id),card=el('article'),symbol=el('span',own?r.glyph:'◇');card.style.setProperty('--relic',r.color);symbol.className='relic-gem';card.append(symbol,el('h4',own?r.name:'Undiscovered · chapter '+r.chapter));if(own){card.append(el('p',r.effect),el('small',r.lore));const wearer=s.heroes.find(v=>equippedRelics(v).includes(r.id));if(wearer)card.append(el('p','Carried by '+wearer.name));for(let slot=0;slot<2;slot++){const b=el('button','Equip in slot '+(slot+1));b.disabled=s.mode==='battle'||!!wearer;b.onclick=()=>{if(equipCombatRelic(s,hero,r.id,slot)){onSave();paint();}};card.append(b);}}else card.append(el('p','Restore this region’s physical lore mechanism and search the opened cache site.'));root.append(card);}
 const rules=el('details'),summary=el('summary','How battle reactions work');rules.append(summary);for(const r of REACTION_RULES){rules.append(el('h4',r.name+' · '+r.trigger),el('p',r.effect));}rules.append(el('p','Location tags come from the current room or biome. Rain begins a fight with wet footing. Reactions consume conditions, arc once, and have capped multipliers.'));root.append(rules);const back=el('button','Back to pause');back.onclick=onBack;root.append(back);}paint();return root;}
export function battleConditionHud(battle){let box=document.querySelector('#battle-conditions');if(!box){box=document.createElement('aside');box.id='battle-conditions';document.querySelector('#commands').prepend(box);}box.hidden=!battle;if(!battle)return;const tags=battle.context?.tags||[],last=battle.events.filter(e=>e.type==='reaction').slice(-2).map(e=>e.label),text=(tags.length?'Ground: '+tags.join(' · '):'Ground: neutral')+' · '+battle.heroes.map(h=>h.name+': '+(approachFor(h)?.name||'open approach')).join(' / ')+(last.length?' — '+last.join(' → '):'');if(box.textContent!==text)box.textContent=text;}
